// What `strip-claude-footer.yml` removes, tried on the endings actually met in
// Reefact/conventional-comments-toolkit: #165 (the session's form) and #167 (the form the
// creation tool adds). Built-in `node:test`, so it needs nothing installed:
//
//   node --test .github/scripts/claude-footer.test.mjs
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import {
  endsWithSessionMarker,
  stripClaudeFooter,
  stripClaudeFooterAfterSessionMarker,
} from './claude-footer.mjs';

const BODY = '## Checks\n\n`dotnet test`: green on both legs.';
const SESSION = 'https://claude.ai/code/session_019k6GsTFFw5SmEGKBtGSif6';
const SESSION_FORM = `🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\n${SESSION}`;
const TOOL_FORM = `---\n_Generated by [Claude Code](${SESSION})_`;

describe('stripClaudeFooter (descriptions)', () => {
  it("removes the session's form, link included", () => {
    assert.equal(stripClaudeFooter(`${BODY}\n\n${SESSION_FORM}`), BODY);
  });

  it("removes the session's form without its link", () => {
    const footer = '🤖 Generated with [Claude Code](https://claude.com/claude-code)';
    assert.equal(stripClaudeFooter(`${BODY}\n\n${footer}`), BODY);
  });

  it('removes the form the creation tool adds', () => {
    assert.equal(stripClaudeFooter(`${BODY}\n\n${TOOL_FORM}`), BODY);
  });

  it("removes both forms when the tool adds its own after the session's", () => {
    assert.equal(stripClaudeFooter(`${BODY}\n\n${SESSION_FORM}\n\n${TOOL_FORM}`), BODY);
  });

  it('removes a session link left alone on the last line, with or without the footer after it', () => {
    assert.equal(stripClaudeFooter(`${BODY}\n\n${SESSION}`), BODY);
    assert.equal(stripClaudeFooter(`${BODY}\n\n${SESSION}\n\n${TOOL_FORM}`), BODY);
  });

  it('keeps a session link quoted in the middle of the text', () => {
    const body = `See ${SESSION} for the original session.\n\nEnd.`;
    assert.equal(stripClaudeFooter(body), body);
  });

  it('accepts CRLF line endings and trailing whitespace', () => {
    const crlf = `${BODY}\n\n${TOOL_FORM}\n\n`.replace(/\n/g, '\r\n');
    assert.equal(stripClaudeFooter(crlf), BODY);
  });

  it('leaves a description that does not end with a footer untouched', () => {
    const quoted = `The footer "${SESSION_FORM}" is removed.\n\nEnd.`;
    assert.equal(stripClaudeFooter(quoted), quoted);
    assert.equal(stripClaudeFooter(BODY), BODY);
  });

  it('keeps a horizontal rule that does not precede the footer', () => {
    const body = `${BODY}\n\n---\n\nAppendix.`;
    assert.equal(stripClaudeFooter(body), body);
  });

  it('returns an empty description when it held nothing but the footer', () => {
    assert.equal(stripClaudeFooter(TOOL_FORM), '');
    assert.equal(stripClaudeFooter(null), '');
  });
});

describe('stripClaudeFooterAfterSessionMarker (comments)', () => {
  const REPLY = 'done: the guard is back on one line in 51f5cde\n\nThe suite builds.';
  const MARKED = `${REPLY}\n\n[session:tedious-debated-branch]`;
  const COMMENT_FOOTER = '---\n_Generated by [Claude Code](https://claude.ai/code)_';

  it('removes the footer when a session marker precedes it, which is then the last line', () => {
    const stripped = stripClaudeFooterAfterSessionMarker(`${MARKED}\n\n${COMMENT_FOOTER}`);
    assert.equal(stripped, MARKED);
    assert.equal(stripped.split('\n').pop(), '[session:tedious-debated-branch]');
  });

  it('keeps the footer when no marker precedes it', () => {
    const posted = `${REPLY}\n\n${COMMENT_FOOTER}`;
    assert.equal(stripClaudeFooterAfterSessionMarker(posted), posted);
  });

  it('keeps the footer when the marker sits in a code block or a quotation', () => {
    for (const ending of ['```\n[session:x]\n```', '> [session:x]', '```\n[session:x]']) {
      const posted = `${REPLY}\n\n${ending}\n\n${COMMENT_FOOTER}`;
      assert.equal(stripClaudeFooterAfterSessionMarker(posted), posted);
    }
  });

  it('keeps the footer when the marker has an empty value', () => {
    const posted = `${REPLY}\n\n[session:  ]\n\n${COMMENT_FOOTER}`;
    assert.equal(stripClaudeFooterAfterSessionMarker(posted), posted);
  });

  it('removes a lone session link when a marker precedes it', () => {
    const posted = `${MARKED}\n\nhttps://claude.ai/code/session_xyz`;
    assert.equal(stripClaudeFooterAfterSessionMarker(posted), MARKED);
  });

  it('leaves a comment with no footer untouched', () => {
    assert.equal(stripClaudeFooterAfterSessionMarker(MARKED), MARKED);
    assert.equal(stripClaudeFooterAfterSessionMarker(null), '');
  });
});

// The toolkit holds `endsWithSessionMarker` to its `extractSessionMarker()` with a parity test
// this repository cannot run without building the toolkit. Each expected value below is what
// that original answered for the case, recorded when the module was imported.
describe('endsWithSessionMarker', () => {
  const cases = [
    ['[session:abc]', true],
    ['issue: x\n\n[session:abc]', true],
    ['issue: x\n\n[session:abc]\n\n\n', true],
    ['issue: x\r\n\r\n[session:abc]\r\n', true],
    ['issue: x\n\n  [session:abc]  ', true],
    ['issue: x\n\n[session:a]b]', true],
    ['issue: x\n\n[session:]', false],
    ['issue: x\n\n[session:   ]', false],
    ['issue: x\n\n[Session:abc]', false],
    ['issue: x\n\n[session :abc]', false],
    ['issue: x\n\ntext [session:abc]', false],
    ['issue: x\n\n[session:abc] text', false],
    ['issue: x\n\n> [session:abc]', false],
    ['issue: x\n\n```\n[session:abc]\n```', false],
    ['issue: x\n\n```\n[session:abc]', false],
    ['issue: x\n\n~~~~\n```\n~~~~\n[session:abc]', true],
    ['issue: x\n\n````\n```\n[session:abc]', false],
    ['issue: x\n\n﻿[session:abc] ', true],
    ['', false],
    ['\n\n', false],
  ];

  for (const [body, expected] of cases) {
    it(`${JSON.stringify(body)} -> ${expected}`, () => {
      assert.equal(endsWithSessionMarker(body), expected);
    });
  }
});
